    <a class="skip-link" href="#main">Skip to main content</a>
    <div id="app"></div>

    <script>
      const state = {
        submitted: false,
      };

      function fieldMarkup({ id, label, type, required, autocomplete, helpText, placeholder }) {
        const describedBy = helpText ? `${id}-help ${id}-error` : `${id}-error`;
        const requiredMark = required ? '<span class="required-indicator" aria-hidden="true">*</span>' : '';
        const requiredAttr = required ? 'required aria-required="true"' : '';

        return `
          <div class="form-field">
            <label for="${id}">${label}${requiredMark}</label>
            <input
              id="${id}"
              name="${id}"
              type="${type}"
              ${requiredAttr}
              autocomplete="${autocomplete}"
              aria-describedby="${describedBy}"
              placeholder="${placeholder}"
            />
            ${helpText ? `<p class="field-help" id="${id}-help">${helpText}</p>` : ""}
            <p class="field-error" id="${id}-error" aria-live="polite"></p>
          </div>
        `;
      }

      function supportFormMarkup() {
        return `
          <main id="main" class="page" tabindex="-1">
            <section class="hero" aria-labelledby="page-title">
              <p class="eyebrow">Support</p>
              <h1 id="page-title">Contact our support team</h1>
              <p class="lead">Send us your details and we’ll get back to you as soon as we can.</p>
            </section>

            <section class="layout" aria-label="Contact form and help">
              <div class="panel form-shell">
                <form id="support-form" novalidate>
                  ${fieldMarkup({
                    id: "full-name",
                    label: "Full name",
                    type: "text",
                    required: true,
                    autocomplete: "name",
                    placeholder: "Jane Doe",
                  })}
                  ${fieldMarkup({
                    id: "email-address",
                    label: "Email address",
                    type: "email",
                    required: true,
                    autocomplete: "email",
                    placeholder: "jane@example.com",
                  })}
                  ${fieldMarkup({
                    id: "phone-number",
                    label: "Phone number",
                    type: "tel",
                    required: false,
                    autocomplete: "tel",
                    helpText: "Optional. Use a standard format such as +1 555 123 4567, (555) 123-4567, or 555-123-4567.",
                    placeholder: "+1 555 123 4567",
                  })}

                  <p id="form-status" class="status" role="status" aria-live="polite"></p>

                  <div class="actions">
                    <button type="submit">Send message</button>
                  </div>
                </form>
              </div>

              <aside class="panel support-copy">
                <h2>What to include</h2>
                <p>We use this information only to reach out about your request.</p>
                <ul>
                  <li>Full name and email are required so we can reply.</li>
                  <li>Phone number is optional, but if you add it, keep the format readable.</li>
                  <li>We will only use your details for support follow-up.</li>
                </ul>
              </aside>
            </section>

            <footer>
              Need a faster reply? Include a clear description of the issue in your support message.
            </footer>
          </main>
        `;
      }

      function renderApp() {
        document.getElementById("app").innerHTML = supportFormMarkup();
        wireForm();
      }

      function normalizePhone(value) {
        return value.replace(/[\s().-]/g, "");
      }

      function validateField(input) {
        const value = input.value.trim();
        const errorEl = document.getElementById(`${input.id}-error`);
        let message = "";

        if (input.id === "full-name") {
          if (!value) {
            message = "Full name is required.";
          } else if (value.length < 2) {
            message = "Enter a full name with at least 2 characters.";
          }
        }

        if (input.id === "email-address") {
          if (!value) {
            message = "Email address is required.";
          } else if (!input.checkValidity()) {
            message = "Enter a valid email address, such as jane@example.com.";
          }
        }

        if (input.id === "phone-number" && value) {
          const digits = normalizePhone(value).replace(/^\+/, "");
          const digitCount = digits.replace(/\D/g, "").length;
          const allowed = /^[+0-9()\-.\s]+$/.test(value);
          if (!allowed || digitCount < 7) {
