         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         color: var(--text);
         background:
           radial-gradient(circle at top left, #dce7ff 0, #dce7ff 18%, transparent 19%),
           radial-gradient(circle at top right, #d7f3ff 0, #d7f3ff 16%, transparent 17%),
           var(--bg);
         min-height: 100vh;
       }

       a {
         color: var(--accent);
       }

       .skip-link {
         position: absolute;
         left: 1rem;
         top: 1rem;
         padding: 0.75rem 1rem;
         background: var(--surface);
         color: var(--text);
         border: 2px solid var(--accent);
         border-radius: 999px;
         transform: translateY(-180%);
         transition: transform 0.2s ease;
         z-index: 10;
       }

       .skip-link:focus {
         transform: translateY(0);
         outline: none;
       }

       .page {
         width: min(100%, 1120px);
         margin: 0 auto;
         padding: 1.25rem;
       }

       .hero {
         display: grid;
         gap: 1rem;
         align-items: end;
         margin-top: 1.25rem;
         padding: 1.5rem 1.5rem 0;
       }

       .eyebrow {
         margin: 0;
         font-size: 0.875rem;
         font-weight: 700;
         letter-spacing: 0.08em;
         text-transform: uppercase;
         color: var(--accent-dark);
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 5vw, 3.5rem);
         line-height: 1.05;
         letter-spacing: -0.04em;
       }

       .lead {
         margin: 0;
         max-width: 62ch;
         color: var(--muted);
         font-size: 1.05rem;
         line-height: 1.6;
       }

       .layout {
         display: grid;
         gap: 1.25rem;
         grid-template-columns: 1.2fr 0.8fr;
         align-items: start;
         padding: 1.5rem;
       }

       .panel {
         background: var(--surface);
         border: 1px solid #dbe3f0;
         border-radius: var(--radius);
         box-shadow: var(--shadow);
       }

       .form-shell {
         padding: clamp(1.25rem, 2vw, 2rem);
       }

       .support-copy {
         padding: clamp(1.25rem, 2vw, 2rem);
         background: linear-gradient(180deg, #f9fbff 0%, #eef4ff 100%);
       }

       .support-copy h2 {
         margin-top: 0;
         font-size: 1.35rem;
       }

       .support-copy p,
       .support-copy li {
         color: var(--muted);
         line-height: 1.6;
       }

       .support-copy ul {
         padding-left: 1.25rem;
         margin: 0.75rem 0 0;
       }

       form {
         display: grid;
         gap: 1rem;
       }

       .form-field {
         display: grid;
         gap: 0.45rem;
       }

       label {
         font-weight: 600;
         color: var(--text);
       }

       .required-indicator {
         color: var(--error);
         margin-left: 0.2rem;
       }

       .field-help {
         margin: 0;
         color: var(--muted);
         font-size: 0.95rem;
         line-height: 1.45;
       }

       .field-error {
         margin: 0;
         min-height: 1.2em;
         color: var(--error);
         font-size: 0.95rem;
       }

       input {
         width: 100%;
         border: 1px solid var(--border);
         border-radius: 14px;
         padding: 0.9rem 1rem;
         font: inherit;
         color: var(--text);
         background: var(--surface-alt);
         transition: border-color 0.15s ease, box-shadow 0.15s ease, background-color 0.15s ease;
       }

       input::placeholder {
         color: #7a8496;
       }

       input:hover {
         border-color: var(--border-strong);
       }

       input:focus {
         outline: none;
         border-color: var(--accent);
         box-shadow: var(--focus);
         background: var(--surface);
       }

       input[aria-invalid="true"] {
         border-color: var(--error);
         background: var(--error-bg);
       }

       .status {
         min-height: 1.5rem;
         margin: 0;
         font-size: 0.98rem;
         color: var(--success-text);
       }

       .status[data-state="error"] {
         color: var(--error);
       }

       .actions {
         display: flex;
         justify-content: flex-start;
         align-items: center;
         gap: 0.75rem;
         margin-top: 0.25rem;
       }

       button {
         appearance: none;
         border: 1px solid transparent;
         border-radius: 999px;
         padding: 0.9rem 1.25rem;
         font: inherit;
         font-weight: 700;
         color: #ffffff;
         background: linear-gradient(180deg, var(--accent) 0%, var(--accent-dark) 100%);
         cursor: pointer;
         box-shadow: 0 10px 24px #2457ff33;
         transition: transform 0.15s ease, box-shadow 0.15s ease;
       }

       button:hover {
         transform: translateY(-1px);
         box-shadow: 0 14px 28px #2457ff3d;
       }

       button:focus {
         outline: none;
         box-shadow: var(--focus), 0 10px 24px #2457ff33;
       }

       footer {
         padding: 0 1.5rem 1.5rem;
         color: var(--muted);
         font-size: 0.95rem;
       }

       .visually-hidden {
         position: absolute;
         width: 1px;
         height: 1px;
         padding: 0;
         margin: -1px;
         overflow: hidden;
         clip: rect(0, 0, 0, 0);
         white-space: nowrap;
         border: 0;
       }

       @media (max-width: 860px) {
         .layout {
           grid-template-columns: 1fr;
         }
       }

       @media (max-width: 640px) {
         .page,
         .hero,
         .layout,
         footer {
           padding-left: 1rem;
           padding-right: 1rem;
         }

         .hero {
           padding-top: 1rem;
         }
       }

       @media (forced-colors: active) {
         :root {
           --bg: Canvas;
           --surface: Canvas;
           --surface-alt: Canvas;
           --text: CanvasText;
           --muted: CanvasText;
           --border: ButtonBorder;
           --border-strong: ButtonBorder;
           --accent: LinkText;
           --accent-dark: LinkText;
           --error: CanvasText;
           --error-bg: Canvas;
           --success-bg: Canvas;
           --success-text: CanvasText;
           --shadow: none;
           --focus: 0 0 0 2px Highlight;
         }

         .panel,
         input,
         button {
           forced-color-adjust: auto;
         }

         button {
           border-color: ButtonBorder;
         }
       }
     </style>
