       function normalizePhone(value) {
         return value.replace(/[\s().-]/g, "");
       }

       function validateField(input) {
         const value = input.value.trim();
         const errorEl = document.getElementById(`${input.id}-error`);
         let message = "";

         if (input.id === "full-name") {
           if (!value) {
             message = "Full name is required.";
           } else if (value.length < 2) {
             message = "Enter a full name with at least 2 characters.";
           }
         }

         if (input.id === "email-address") {
           if (!value) {
             message = "Email address is required.";
           } else if (!input.checkValidity()) {
             message = "Enter a valid email address, such as jane@example.com.";
           }
         }

         if (input.id === "phone-number" && value) {
           const digits = normalizePhone(value).replace(/^\+/, "");
           const digitCount = digits.replace(/\D/g, "").length;
           const allowed = /^[+0-9()\-.\s]+$/.test(value);
           if (!allowed || digitCount < 7) {
             message = "Enter a valid phone number using digits, spaces, dashes, parentheses, or +.";
           }
         }

         const invalid = Boolean(message);
         input.setAttribute("aria-invalid", invalid ? "true" : "false");
         errorEl.textContent = message;
         return !invalid;
       }

       function setStatus(message, stateName) {
         const status = document.getElementById("form-status");
         status.textContent = message;
         status.dataset.state = stateName;
       }

       function wireForm() {
         const form = document.getElementById("support-form");
         const inputs = Array.from(form.querySelectorAll("input"));

         inputs.forEach((input) => {
           input.addEventListener("blur", () => validateField(input));
           input.addEventListener("input", () => {
             if (input.getAttribute("aria-invalid") === "true" || state.submitted) {
               validateField(input);
             }
           });
         });

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           state.submitted = true;

           const firstInvalid = inputs.find((input) => !validateField(input));
           if (firstInvalid) {
             setStatus("Please fix the highlighted fields and try again.", "error");
             firstInvalid.focus();
             return;
           }

           setStatus("Thanks — your message is ready to send.", "success");
           form.reset();
           inputs.forEach((input) => {
             input.removeAttribute("aria-invalid");
             document.getElementById(`${input.id}-error`).textContent = "";
           });
         });
